"""
    Group a list into groups of adjacent elements. e.g.

    > group(list("AAABBCCDBBBBA"))
    [("A", 3), ("B", 2), ("C", 2), ("D", 1), ("B", 4), ("A", 1)]
    """
def group(l: Any) -> object {
    result = [];
    previous = None;
    count = 0;
    for elem in l {
        if (previous is None) {
            previous = elem;
            count = 1;
        } elif (previous == elem) {
            count += 1;
        } else {
            result.append((previous, count));
            previous = elem;
            count = 1;
        }
    }
    if (previous is not None) {
        result.append((previous, count));
    }
    return result;
}

"""Returns a compact string describing the firewall rules."""
def _FirewallRulesToCell(firewall: Any) -> object {
    rules = [];
    for allowed in firewall.get('allowed', []) {
        protocol = allowed.get('IPProtocol');
        if not protocol {
            continue;
        }
        port_ranges = allowed.get('ports');
        if port_ranges {
            for port_range in port_ranges {
                rules.append('{0}:{1}'.format(protocol, port_range));
            }
        } else {
            rules.append(protocol);
        }
    }
    return ','.join(rules);
}

