"""
    min : integer
    max: integer
    value : value element DOM. Example : document['id].value
    message_error : str message
    message_valid: str message
    function return tuple
    """
def lenght(
    value: Any, min: Any, max: Any, message_error: Any = None, message_valid: Any = None
) -> object {
    if ((min is not None) and (len(value) < min)) {
        return (
            False,
            (message_error or ('length of value must be at least %s' % min)),
            value
        );
    }
    if ((max is not None) and (len(value) > max)) {
        return (
            False,
            (message_error or ('length of value must be at most %s' % min)),
            value
        );
    } else {
        return (True, (message_valid or 'valid'), value);
    }
}

